// Compartido: cuerpos para la Bot API de Telegram (parse_mode HTML).
// @exports escapeHtml, tgMessage, tgEditMessage, splitTelegram

function escapeHtml(s) {
  return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

/** Cuerpo de sendMessage. buttons: [[{text, data}]] → teclado inline. */
function tgMessage(chatId, html, buttons) {
  const body = { chat_id: chatId, text: html, parse_mode: "HTML", disable_web_page_preview: true };
  if (buttons && buttons.length) {
    body.reply_markup = { inline_keyboard: buttons.map((row) => row.map((b) => ({ text: b.text, callback_data: b.data }))) };
  }
  return body;
}

/** Cuerpo de editMessageText (quita los botones al confirmar una acción). */
function tgEditMessage(chatId, messageId, html) {
  return { chat_id: chatId, message_id: messageId, text: html, parse_mode: "HTML", disable_web_page_preview: true, reply_markup: { inline_keyboard: [] } };
}

/** Telegram limita a 4096 caracteres: parte por párrafos. */
function splitTelegram(text, max) {
  const limit = max || 4000;
  if (text.length <= limit) return [text];
  const chunks = [];
  let current = "";
  for (const para of text.split(/\n\n+/)) {
    if ((current + "\n\n" + para).length > limit && current) {
      chunks.push(current);
      current = para;
    } else current = current ? current + "\n\n" + para : para;
  }
  if (current) chunks.push(current);
  return chunks.flatMap((c) => (c.length <= limit ? [c] : c.match(new RegExp(`[\\s\\S]{1,${limit}}`, "g"))));
}
function run(geminiItem, eventItem, env) {
  const e = eventItem.json;
  const r = e.data || {};
  const resumen = parseGeminiText(geminiItem && geminiItem.json);
  const base = (env.FOODZINDER_BASE_URL || "https://foodzinder.vercel.app").replace(/\/+$/, "");
  const reenvio = e.event === "restaurant.resubmitted";
  const cocinas = (r.cuisines || []).map((c) => c.name || c).join(", ");

  const lines = [
    `<b>${reenvio ? "Restaurante reenviado tras rechazo" : "Nuevo restaurante pendiente"}</b>`,
    `<b>${escapeHtml(r.name)}</b>${r.city ? ` · ${escapeHtml(r.city)}` : ""}${cocinas ? ` · ${escapeHtml(cocinas)}` : ""}`,
    `Dueño: ${escapeHtml((r.owner && (r.owner.name || r.owner.email)) || "sin indicar")}${r.owner && r.owner.email ? ` (${escapeHtml(r.owner.email)})` : ""}`,
    "",
    resumen ? escapeHtml(resumen) : `Sin resumen de IA. Precio: ${escapeHtml(r.priceRange || "sin indicar")}. ${r.description ? escapeHtml(String(r.description).slice(0, 300)) : "Sin descripción."}`,
    "",
    `<a href="${base}/dashboard/admin/restaurants/${r.id}">Ver ficha en el panel</a>`,
  ];
  const text = lines.join("\n");
  const buttons = [[{ text: "✅ Aprobar", data: `approve:${r.id}` }, { text: "❌ Rechazar", data: `reject:${r.id}` }]];
  return [{ json: { ...e, action: "telegram-admin", aiUsed: Boolean(resumen), telegramBody: tgMessage(env.TELEGRAM_ADMIN_CHAT_ID, text, buttons) } }];
}

return run($input.first(), $("preparar-resumen").first(), $env); // @n8n-invoke

// Nodo Code "registrar": última parada de cada rama. Deja una línea legible en
// la ejecución para auditar qué se hizo con cada evento.
function run(items, now) {
  return items.map((item) => {
    const e = item.json;
    const summary = `${e.event} ${e.id} -> ${e.action || "sin acción"}: ${e.result || "ok"}`;
    return { json: { ...e, summary, loggedAt: (now || new Date()).toISOString() } };
  });
}

return run($input.all(), new Date()); // @n8n-invoke
